# -*- coding: utf-8 -*-
"""Lecture 31 vignette pool C -- Pericardial Disease: cardiac tamponade, its mimics,
stabilization and drainage, and effusive-constrictive pericarditis.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Tamponade is keyed as a clinical diagnosis confirmed by the response to drainage
(s57), never "confirmed by echo"; the Kussmaul sign is never a tamponade finding;
no pressor names or fluid rates (the lecturer's own cap). Named findings carry
their description in parentheses.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l31_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


